CREATE TABLE IF NOT EXISTS schema_migrations (version text PRIMARY KEY, applied_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE roles (name text PRIMARY KEY CHECK(name IN ('SUPER_ADMIN','STAFF','CUSTOMER')));
INSERT INTO roles VALUES ('SUPER_ADMIN'),('STAFF'),('CUSTOMER');
CREATE TABLE users (id text PRIMARY KEY DEFAULT gen_random_uuid()::text, email text UNIQUE NOT NULL, password_hash text NOT NULL, name text NOT NULL, role text NOT NULL DEFAULT 'CUSTOMER' REFERENCES roles(name), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE customer_profiles (user_id text PRIMARY KEY REFERENCES users ON DELETE CASCADE, phone text NOT NULL DEFAULT '', address text NOT NULL DEFAULT '');
CREATE TABLE sessions (token_hash text PRIMARY KEY, user_id text NOT NULL REFERENCES users ON DELETE CASCADE, expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX sessions_user_idx ON sessions(user_id);
CREATE TABLE destinations (id text PRIMARY KEY DEFAULT gen_random_uuid()::text, name text NOT NULL UNIQUE, country text NOT NULL DEFAULT 'Philippines', description text NOT NULL, image_url text NOT NULL, featured boolean NOT NULL DEFAULT false);
CREATE TABLE packages (id text PRIMARY KEY DEFAULT gen_random_uuid()::text, destination_id text NOT NULL REFERENCES destinations, slug text NOT NULL UNIQUE, title text NOT NULL, description text NOT NULL, category text NOT NULL, duration integer NOT NULL CHECK(duration BETWEEN 1 AND 90), min_participants integer NOT NULL DEFAULT 1 CHECK(min_participants>0), max_participants integer NOT NULL DEFAULT 20 CHECK(max_participants>=min_participants), meeting_point text NOT NULL, transportation text NOT NULL, accommodation text NOT NULL, meals text NOT NULL, guide text NOT NULL, inclusions jsonb NOT NULL DEFAULT '[]', exclusions jsonb NOT NULL DEFAULT '[]', policies text NOT NULL, notes text NOT NULL DEFAULT '', status text NOT NULL DEFAULT 'DRAFT' CHECK(status IN ('DRAFT','PUBLISHED','ARCHIVED')), featured boolean NOT NULL DEFAULT false, demo boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE package_images (id text PRIMARY KEY DEFAULT gen_random_uuid()::text, package_id text NOT NULL REFERENCES packages ON DELETE CASCADE, url text NOT NULL, alt text NOT NULL, position integer NOT NULL DEFAULT 0);
CREATE TABLE package_pricing (package_id text PRIMARY KEY REFERENCES packages ON DELETE CASCADE, adult_price integer NOT NULL CHECK(adult_price>0), child_price integer NOT NULL CHECK(child_price>=0), deposit_percent integer NOT NULL DEFAULT 30 CHECK(deposit_percent BETWEEN 1 AND 100));
CREATE TABLE itinerary_days (id text PRIMARY KEY DEFAULT gen_random_uuid()::text, package_id text NOT NULL REFERENCES packages ON DELETE CASCADE, day integer NOT NULL CHECK(day>0), title text NOT NULL, UNIQUE(package_id,day));
CREATE TABLE itinerary_activities (id text PRIMARY KEY DEFAULT gen_random_uuid()::text, day_id text NOT NULL REFERENCES itinerary_days ON DELETE CASCADE, sequence integer NOT NULL DEFAULT 0, time_label text NOT NULL, title text NOT NULL, description text NOT NULL, location text NOT NULL DEFAULT '', photo_url text, included boolean NOT NULL DEFAULT true);
CREATE TABLE departures (id text PRIMARY KEY DEFAULT gen_random_uuid()::text, package_id text NOT NULL REFERENCES packages, departure_at timestamptz NOT NULL, booking_deadline timestamptz NOT NULL, capacity integer NOT NULL CHECK(capacity>0), reserved integer NOT NULL DEFAULT 0 CHECK(reserved>=0 AND reserved<=capacity), price_adjustment integer NOT NULL DEFAULT 0, available boolean NOT NULL DEFAULT true, UNIQUE(package_id,departure_at), CHECK(booking_deadline<departure_at));
CREATE INDEX departures_date_idx ON departures(departure_at);
CREATE TABLE promotions (id text PRIMARY KEY DEFAULT gen_random_uuid()::text, name text NOT NULL, code text NOT NULL UNIQUE, discount_type text NOT NULL CHECK(discount_type IN ('PERCENT','FIXED')), value integer NOT NULL CHECK(value>0), starts_at timestamptz NOT NULL, ends_at timestamptz NOT NULL, usage_limit integer NOT NULL CHECK(usage_limit>0), used integer NOT NULL DEFAULT 0 CHECK(used>=0 AND used<=usage_limit), min_total integer NOT NULL DEFAULT 0 CHECK(min_total>=0), active boolean NOT NULL DEFAULT true, CHECK(ends_at>starts_at), CHECK(discount_type!='PERCENT' OR value<=100));
CREATE TABLE promotion_packages (promotion_id text NOT NULL REFERENCES promotions ON DELETE CASCADE, package_id text NOT NULL REFERENCES packages, PRIMARY KEY(promotion_id,package_id));
CREATE TABLE bookings (id text PRIMARY KEY DEFAULT gen_random_uuid()::text, reference text NOT NULL UNIQUE, user_id text REFERENCES users, departure_id text NOT NULL REFERENCES departures, contact_name text NOT NULL, contact_email text NOT NULL, contact_phone text NOT NULL, adults integer NOT NULL CHECK(adults>=1), children integer NOT NULL DEFAULT 0 CHECK(children>=0), subtotal integer NOT NULL CHECK(subtotal>0), discount integer NOT NULL DEFAULT 0 CHECK(discount>=0), total integer NOT NULL CHECK(total>0), deposit_due integer NOT NULL CHECK(deposit_due>0 AND deposit_due<=total), payment_method text NOT NULL CHECK(payment_method IN ('GCASH','MAYA','BANK','CASH')), status text NOT NULL DEFAULT 'PENDING_PAYMENT' CHECK(status IN ('PENDING_REVIEW','PENDING_PAYMENT','PAYMENT_UNDER_REVIEW','CONFIRMED','COMPLETED','CANCELLED','REFUND_PENDING','REFUNDED')), snapshot jsonb NOT NULL, guest_token_hash text NOT NULL, expires_at timestamptz, cancellation_reason text, seats_released boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CHECK(total=subtotal-discount));
CREATE INDEX bookings_user_idx ON bookings(user_id);
CREATE INDEX bookings_departure_idx ON bookings(departure_id);
CREATE INDEX bookings_status_idx ON bookings(status);
CREATE TABLE booking_travelers (id text PRIMARY KEY DEFAULT gen_random_uuid()::text, booking_id text NOT NULL REFERENCES bookings ON DELETE CASCADE, name text NOT NULL, type text NOT NULL CHECK(type IN ('ADULT','CHILD')));
CREATE TABLE promotion_usage (promotion_id text NOT NULL REFERENCES promotions, booking_id text UNIQUE NOT NULL REFERENCES bookings, PRIMARY KEY(promotion_id,booking_id));
CREATE TABLE payment_submissions (id text PRIMARY KEY DEFAULT gen_random_uuid()::text, booking_id text NOT NULL REFERENCES bookings, amount integer NOT NULL CHECK(amount>0), method text NOT NULL CHECK(method IN ('GCASH','MAYA','BANK','CASH')), reference text NOT NULL, status text NOT NULL DEFAULT 'UNDER_REVIEW' CHECK(status IN ('UNDER_REVIEW','VERIFIED','REJECTED')), review_note text, reviewed_by text REFERENCES users, created_at timestamptz NOT NULL DEFAULT now(), reviewed_at timestamptz, UNIQUE(method,reference));
CREATE TABLE payments (id text PRIMARY KEY DEFAULT gen_random_uuid()::text, booking_id text NOT NULL REFERENCES bookings, submission_id text UNIQUE REFERENCES payment_submissions, amount integer NOT NULL CHECK(amount>0), kind text NOT NULL CHECK(kind IN ('PAYMENT','REFUND')), reference text NOT NULL, recorded_by text NOT NULL REFERENCES users, paid_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX payments_booking_idx ON payments(booking_id);
CREATE TABLE custom_inquiries (id text PRIMARY KEY DEFAULT gen_random_uuid()::text, user_id text REFERENCES users, name text NOT NULL, email text NOT NULL, phone text NOT NULL, destination text NOT NULL, start_date date NOT NULL, end_date date NOT NULL, travelers integer NOT NULL CHECK(travelers>0), budget integer NOT NULL CHECK(budget>0), accommodation text NOT NULL, interests text NOT NULL, requests text NOT NULL DEFAULT '', status text NOT NULL DEFAULT 'NEW' CHECK(status IN ('NEW','IN_PROGRESS','QUOTED','CLOSED')), created_at timestamptz NOT NULL DEFAULT now(), CHECK(end_date>=start_date));
CREATE TABLE inquiry_quotations (id text PRIMARY KEY DEFAULT gen_random_uuid()::text, inquiry_id text NOT NULL REFERENCES custom_inquiries, amount integer NOT NULL CHECK(amount>0), message text NOT NULL, created_by text NOT NULL REFERENCES users, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE reviews (id text PRIMARY KEY DEFAULT gen_random_uuid()::text, booking_id text UNIQUE NOT NULL REFERENCES bookings, user_id text NOT NULL REFERENCES users, package_id text NOT NULL REFERENCES packages, rating integer NOT NULL CHECK(rating BETWEEN 1 AND 5), body text NOT NULL, status text NOT NULL DEFAULT 'PENDING' CHECK(status IN ('PENDING','APPROVED','REJECTED')), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE notifications (id text PRIMARY KEY DEFAULT gen_random_uuid()::text, user_id text REFERENCES users ON DELETE CASCADE, booking_id text REFERENCES bookings, title text NOT NULL, message text NOT NULL, read_at timestamptz, email_status text NOT NULL DEFAULT 'NOT_CONFIGURED' CHECK(email_status IN ('NOT_CONFIGURED','PENDING','SENT','FAILED')), created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX notifications_user_idx ON notifications(user_id);
CREATE TABLE website_content (key text PRIMARY KEY, title text NOT NULL, body text NOT NULL, updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE app_settings (key text PRIMARY KEY, value jsonb NOT NULL, updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE audit_logs (id text PRIMARY KEY DEFAULT gen_random_uuid()::text, actor_id text NOT NULL REFERENCES users, action text NOT NULL, entity_type text NOT NULL, entity_id text NOT NULL, detail jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE rate_limits (key text PRIMARY KEY, count integer NOT NULL DEFAULT 1, reset_at timestamptz NOT NULL);
